/* clock — synced to system time, updates every second */
function updateClock(){
  const d=new Date();
  const h=String(d.getHours()).padStart(2,'0');
  const m=String(d.getMinutes()).padStart(2,'0');
  const s=String(d.getSeconds()).padStart(2,'0');
  document.getElementById('clock').textContent=h+':'+m+':'+s;
}
updateClock();
setInterval(updateClock, 1000);

/* tabs + audio */
const clickAudio = new Audio('data:audio/mp3;base64,');
clickAudio.volume = 0.7;
function playClick(){
  try{
    const c = new Audio(clickAudio.src);
    c.volume = 0.7;
    c.play().catch(()=>{});
  }catch(e){}
}

const tabOrder = ['main','treasures','quests','fandom','about'];
const paths={main:'[ home ]',treasures:'[ treasures ]',quests:'[ quest log ]',fandom:'[ fandom ]',about:'[ about ]'};
function setTab(id){
  playClick();
  document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===id));
  document.querySelectorAll('.tab-panel').forEach(p=>p.classList.toggle('active',p.id==='panel-'+id));
  document.getElementById('pathInput').value=paths[id]||'[ '+id+' ]';
  const idx=tabOrder.indexOf(id);
  document.getElementById('arrowBack').style.opacity=idx<=0?'0.4':'1';
  document.getElementById('arrowFwd').style.opacity=idx>=tabOrder.length-1?'0.4':'1';
}
function tabNav(dir){
  const active=document.querySelector('.tab.active');
  if(!active)return;
  const idx=tabOrder.indexOf(active.dataset.tab);
  const next=tabOrder[idx+dir];
  if(next) setTab(next);
}

