/* drag */
(()=>{
  const h=document.getElementById('dragHandle'); let drag=false,ox=0,oy=0;
  h.addEventListener('mousedown',e=>{
    if(e.target.classList.contains('win-btn'))return;
    drag=true;
    const r=win.getBoundingClientRect();
    ox=e.clientX-r.left; oy=e.clientY-r.top;
    // Freeze current size so it doesn't reflow when position changes
    win.style.width=r.width+'px';
    win.style.position='fixed'; win.style.zIndex=100; win.style.margin='0';
    win.style.left=r.left+'px'; win.style.top=r.top+'px';
    document.body.style.cursor='move';
  });
  document.addEventListener('mousemove',e=>{if(drag){win.style.left=(e.clientX-ox)+'px';win.style.top=(e.clientY-oy)+'px';}});
  document.addEventListener('mouseup',()=>{drag=false;document.body.style.cursor='';});
})();

