const ytPlaylist = [
  { id: 'dxxBbwCtR_s', title: 'like a raspberry — 宇宙ネコ子' },
  { id: 'RnatkV_92Bw', title: 'simulation swarm — big thief' },
  { id: 'tITsAJE-X7A', title: 'morning grace — ritsuko okazaki' },
];
let ytIdx = 0, ytReady = false, ytInst = null;

// Load YouTube IFrame API
(function(){
  const tag = document.createElement('script');
  tag.src = 'https://www.youtube.com/iframe_api';
  document.head.appendChild(tag);
})();

window.onYouTubeIframeAPIReady = function(){
  ytInst = new YT.Player('ytPlayer', {
    height:'1', width:'1',
    videoId: ytPlaylist[0].id,
    playerVars:{ autoplay:0, controls:0, disablekb:1, fs:0, rel:0, playsinline:1 },
    events:{
      onReady: function(e){
        ytReady = true;
        e.target.setVolume(60);
        document.getElementById('ytStatus').textContent = '· ready ·';
        document.getElementById('musicTrackName').textContent = '♩ ' + ytPlaylist[0].title;
      },
      onStateChange: function(e){
        if(e.data === YT.PlayerState.PLAYING){
          document.getElementById('musicPlayBtn').textContent = '||';
          document.getElementById('ytStatus').textContent = '· playing ·';
        } else if(e.data === YT.PlayerState.PAUSED){
          document.getElementById('musicPlayBtn').textContent = '▶';
          document.getElementById('ytStatus').textContent = '· paused ·';
        } else if(e.data === YT.PlayerState.ENDED){
          musicNext();
        } else if(e.data === YT.PlayerState.BUFFERING){
          document.getElementById('ytStatus').textContent = '· loading ·';
        }
      },
      onError: function(){
        document.getElementById('ytStatus').textContent = '· unavailable ·';
      }
    }
  });
};

function musicToggle(){
  if(!ytReady) return;
  const s = ytInst.getPlayerState();
  if(s === YT.PlayerState.PLAYING) ytInst.pauseVideo();
  else ytInst.playVideo();
}
function musicNext(){
  ytIdx = (ytIdx + 1) % ytPlaylist.length;
  ytLoadTrack(ytIdx);
}
function musicPrev(){
  ytIdx = (ytIdx - 1 + ytPlaylist.length) % ytPlaylist.length;
  ytLoadTrack(ytIdx);
}
function ytLoadTrack(idx){
  if(!ytReady) return;
  ytInst.loadVideoById(ytPlaylist[idx].id);
  document.getElementById('musicTrackName').textContent = '♩ ' + ytPlaylist[idx].title;
}
function ytSetVol(v){
  if(ytReady) ytInst.setVolume(parseInt(v));
}

/* ── window resize ── */
(()=>{
  const grip = document.getElementById('resizeGrip');
  let resizing = false, startX, startY, startW, startH;
  grip.addEventListener('mousedown', e => {
    e.preventDefault();
    resizing = true;
    startX = e.clientX; startY = e.clientY;
    const r = win.getBoundingClientRect();
    startW = r.width; startH = r.height;
    document.body.style.cursor = 'se-resize';
    document.body.style.userSelect = 'none';
  });
  document.addEventListener('mousemove', e => {
    if(!resizing) return;
    const newW = Math.max(380, Math.min(window.innerWidth - 20, startW + (e.clientX - startX)));
    win.style.width = newW + 'px';
    win.style.maxWidth = newW + 'px';
  });
  document.addEventListener('mouseup', () => {
    if(resizing){ resizing = false; document.body.style.cursor = ''; document.body.style.userSelect = ''; }
  });
})();

/* ── blog (github backend) ── */
var BLOG_PASS_KEY  = 'mary_blog_pass_hash';
var BLOG_TOKEN_KEY = 'mary_blog_gh_token';
var BLOG_OWNER     = 'mryanglrts';   /* ← your GitHub username */
var BLOG_REPO      = 'blog';
var BLOG_FILE      = 'posts.json';
var BLOG_BRANCH    = 'main';
var blogAuthed     = false;

/* simple hash */
function blogHash(s){
  var h=0;
  for(var i=0;i<s.length;i++){ h=((h<<5)-h)+s.charCodeAt(i); h=h|0; }
  return String(h);
}

function blogToggleAuth(){
  if(blogAuthed){ blogLogout(); return; }
  var pw = prompt('enter password:');
  if(!pw) return;
  var stored = localStorage.getItem(BLOG_PASS_KEY);
  if(!stored){
    var confirm = prompt('no password set yet. re-enter to confirm:');
    if(pw !== confirm){ alert('passwords did not match.'); return; }
    localStorage.setItem(BLOG_PASS_KEY, blogHash(pw));
    blogLogin();
  } else {
    if(blogHash(pw) === stored){ blogLogin(); }
    else { document.getElementById('blogAuthStatus').textContent = '· wrong password ·'; }
  }
}

function blogLogin(){
  blogAuthed = true;
  document.getElementById('blogLockBtn').textContent = '· logged in · (lock)';
  document.getElementById('blogWriteForm').style.display   = 'block';
  document.getElementById('blogSettingsBtn').style.display = 'inline-block';
  document.getElementById('blogResetBtn').style.display    = 'inline-block';
  document.getElementById('blogAuthStatus').textContent    = '';
  document.querySelectorAll('.blog-admin-btns').forEach(function(el){ el.style.display='inline-flex'; });
  blogSetDefaultDate();
}

function blogLogout(){
  blogAuthed = false;
  document.getElementById('blogLockBtn').textContent = '· lock ·';
  document.getElementById('blogWriteForm').style.display    = 'none';
  document.getElementById('blogSettingsBtn').style.display  = 'none';
  document.getElementById('blogResetBtn').style.display     = 'none';
  document.getElementById('blogSettingsPanel').style.display= 'none';
  document.getElementById('blogAuthStatus').textContent     = '';
  document.querySelectorAll('.blog-admin-btns').forEach(function(el){ el.style.display='none'; });
}

function blogShowSettings(){
  var panel = document.getElementById('blogSettingsPanel');
  panel.style.display = panel.style.display==='none' ? 'block' : 'none';
  var tok = localStorage.getItem(BLOG_TOKEN_KEY)||'';
  document.getElementById('blogApiKey').value = tok;
  document.getElementById('blogBinId').style.display = 'none';
  document.getElementById('blogBinId').previousElementSibling.style.display = 'none';
}
function blogHideSettings(){
  document.getElementById('blogSettingsPanel').style.display='none';
}
function blogSaveSettings(){
  var tok = document.getElementById('blogApiKey').value.trim();
  if(!tok){ document.getElementById('blogSettingsStatus').textContent='· need a github token ·'; return; }
  localStorage.setItem(BLOG_TOKEN_KEY, tok);
  document.getElementById('blogSettingsStatus').textContent='· saved ✦';
  setTimeout(function(){ document.getElementById('blogSettingsStatus').textContent=''; blogHideSettings(); },1200);
}

function blogToken(){ return localStorage.getItem(BLOG_TOKEN_KEY)||''; }

/* decode base64 content from GitHub API (handles Unicode) */
function blogDecodeContent(raw){
  var binary = atob(raw.split('\n').join(''));
  var bytes = new Uint8Array(binary.length);
  for(var i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}

/* GitHub API — read posts.json */
function blogFetch(){
  document.getElementById('blogLoading').style.display='block';
  document.getElementById('blogFeed').innerHTML='';
  document.getElementById('blogEmpty').style.display='none';

  var url = 'https://api.github.com/repos/'+BLOG_OWNER+'/'+BLOG_REPO+'/contents/'+BLOG_FILE+'?ref='+BLOG_BRANCH+'&t='+Date.now();
  var headers = {'Accept':'application/vnd.github.v3+json'};
  var tok = blogToken();
  if(tok) headers['Authorization'] = 'token '+tok;

  fetch(url, {headers:headers})
  .then(function(r){
    if(r.status===404){ return []; }
    if(!r.ok) throw new Error('status '+r.status);
    return r.json().then(function(d){
      return JSON.parse(blogDecodeContent(d.content));
    });
  })
  .then(function(entries){
    document.getElementById('blogLoading').style.display='none';
    blogRenderEntries(Array.isArray(entries)?entries:[]);
  })
  .catch(function(){
    document.getElementById('blogLoading').style.display='none';
    document.getElementById('blogEmpty').style.display='block';
    document.getElementById('blogEmpty').textContent='· nothing here yet ·';
  });
}

function blogToggleEntry(header){
  var body = header.nextElementSibling;
  var isOpen = body.style.display !== 'none';
  /* collapse all */
  var allBodies = document.querySelectorAll('#blogFeed .blog-entry-body');
  allBodies.forEach(function(b){ b.style.display='none'; });
  /* open clicked if it was closed */
  if(!isOpen) body.style.display='block';
}

function blogRenderEntries(entries){
  var feed  = document.getElementById('blogFeed');
  var empty = document.getElementById('blogEmpty');
  feed.innerHTML='';
  if(!entries.length){ empty.style.display='block'; return; }
  empty.style.display='none';
  var rev = entries.slice().reverse();
  for(var i=0;i<rev.length;i++){
    var e=rev[i]; var ri=entries.length-1-i;
    var sb=e.body.replace(/\n/g,'<br>');
    var st=(e.title||'· untitled ·').replace(/&/g,'&amp;').replace(/</g,'&lt;');
    var div=document.createElement('div');
    div.className='blog-entry';
    var adminBtns='<span class="blog-admin-btns" style="display:'+(blogAuthed?'inline-flex':'none')+';gap:4px;margin-left:auto;">'
      +'<span class="blog-delete" onclick="event.stopPropagation();blogEdit('+ri+')" style="color:var(--sage-dk)">edit</span>'
      +'<span class="blog-delete" onclick="event.stopPropagation();blogDelete('+ri+')">delete</span>'
      +'</span>';
    var bodyDisplay = i===0 ? 'block' : 'none';
    div.innerHTML='<div class="blog-entry-header" onclick="blogToggleEntry(this)" style="cursor:pointer;">'
      +'<span class="blog-entry-title">'+st+'</span>'
      +'<span class="blog-entry-date">'+e.date+'</span>'
      +adminBtns
      +'</div>'
      +'<div class="blog-entry-body" style="display:'+bodyDisplay+'">'+sb+'</div>';
    feed.appendChild(div);
  }
}

/* GitHub API — write posts.json */
function blogGetSHA(cb){
  var url = 'https://api.github.com/repos/'+BLOG_OWNER+'/'+BLOG_REPO+'/contents/'+BLOG_FILE;
  fetch(url,{headers:{'Authorization':'token '+blogToken(),'Accept':'application/vnd.github.v3+json'}})
  .then(function(r){ return r.ok ? r.json() : null; })
  .then(function(d){ cb(d?d.sha:null); })
  .catch(function(){ cb(null); });
}

function blogWriteEntries(entries, statusEl, onDone){
  statusEl.textContent='· saving ·';
  blogGetSHA(function(sha){
    var content = btoa(unescape(encodeURIComponent(JSON.stringify(entries, null, 2))));
    var body = {message:'update blog posts', content:content, branch:BLOG_BRANCH};
    if(sha) body.sha = sha;
    fetch('https://api.github.com/repos/'+BLOG_OWNER+'/'+BLOG_REPO+'/contents/'+BLOG_FILE,{
      method:'PUT',
      headers:{'Authorization':'token '+blogToken(),'Accept':'application/vnd.github.v3+json','Content-Type':'application/json'},
      body:JSON.stringify(body)
    })
    .then(function(r){
      return r.json().then(function(d){ return {ok:r.ok, status:r.status, data:d}; });
    })
    .then(function(res){
      if(!res.ok){
        var msg = res.data && res.data.message ? res.data.message : 'status '+res.status;
        statusEl.textContent='· error: '+msg+' ·';
        return;
      }
      statusEl.textContent='· posted ✦';
      setTimeout(function(){ statusEl.textContent=''; },2000);
      if(onDone) onDone();
    })
    .catch(function(e){ statusEl.textContent='· save failed: '+e.message+' ·'; });
  });
}

function blogPost(){
  if(!blogAuthed) return;
  var title = document.getElementById('blogTitle').value.trim();
  var body  = document.getElementById('blogBody').value.trim();
  if(!body){ document.getElementById('blogPostStatus').textContent='· write something first ·'; return; }
  if(!blogToken()){ document.getElementById('blogPostStatus').textContent='· add your github token in settings first ·'; return; }
  var dateInput = document.getElementById('blogDate').value;
  var dateObj = dateInput ? new Date(dateInput) : new Date();
  var date = dateObj.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})+' - '+dateObj.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
  /* fetch current, append, save */
  var url = 'https://api.github.com/repos/'+BLOG_OWNER+'/'+BLOG_REPO+'/contents/'+BLOG_FILE;
  fetch(url,{headers:{'Authorization':'token '+blogToken(),'Accept':'application/vnd.github.v3+json'}})
  .then(function(r){ return r.ok?r.json():null; })
  .then(function(d){
    var existing = [];
    if(d && d.content){
      try{ existing = JSON.parse(blogDecodeContent(d.content)); }catch(e){}
    }
    var editIdx = parseInt(document.getElementById('blogEditIdx').value);
    if(!isNaN(editIdx) && editIdx >= 0){
      existing[editIdx].title = title;
      existing[editIdx].body  = body;
    } else {
      existing.push({title:title, body:body, date:date});
    }
    blogWriteEntries(existing, document.getElementById('blogPostStatus'), function(){
      document.getElementById('blogTitle').value='';
      document.getElementById('blogBody').value='';
      document.getElementById('blogEditIdx').value='';
      document.getElementById('blogPostBtn').textContent='· post ·';
      blogSetDefaultDate();
      setTimeout(function(){ blogFetch(); }, 2000);
    });
  });
}

function blogDelete(i){
  if(!blogAuthed) return;
  if(!confirm('delete this entry?')) return;
  var url = 'https://api.github.com/repos/'+BLOG_OWNER+'/'+BLOG_REPO+'/contents/'+BLOG_FILE;
  fetch(url,{headers:{'Authorization':'token '+blogToken(),'Accept':'application/vnd.github.v3+json'}})
  .then(function(r){ return r.json(); })
  .then(function(d){
    var entries = JSON.parse(blogDecodeContent(d.content));
    entries.splice(i,1);
    blogWriteEntries(entries, document.getElementById('blogAuthStatus'), function(){ blogFetch(); });
  });
}

/* formatting toolbar */
function blogFmt(type){
  var ta = document.getElementById('blogBody');
  var start = ta.selectionStart, end = ta.selectionEnd;
  var sel = ta.value.substring(start, end);
  var before = ta.value.substring(0, start);
  var after  = ta.value.substring(end);
  var insert = '';
  if(type === 'bold')   insert = '<strong>'+(sel||'bold text')+'</strong>';
  if(type === 'italic') insert = '<em>'+(sel||'italic text')+'</em>';
  if(type === 'bullet') insert = '\n<ul>\n  <li>'+(sel||'item')+'</li>\n</ul>';
  if(type === 'photo'){
    var url = prompt('paste image URL:');
    if(!url) return;
    var alt = prompt('alt text (optional):') || '';
    insert = '\n<img src="'+url+'" alt="'+alt+'" style="max-width:100%;margin:6px 0;display:block;">\n';
  }
  ta.value = before + insert + after;
  ta.focus();
  ta.selectionStart = ta.selectionEnd = before.length + insert.length;
}

function blogSetDefaultDate(){
  var now = new Date();
  var local = new Date(now.getTime() - now.getTimezoneOffset()*60000).toISOString().slice(0,16);
  document.getElementById('blogDate').value = local;
}

function blogEdit(i){
  if(!blogAuthed) return;
  var url = 'https://api.github.com/repos/'+BLOG_OWNER+'/'+BLOG_REPO+'/contents/'+BLOG_FILE;
  fetch(url,{headers:{'Authorization':'token '+blogToken(),'Accept':'application/vnd.github.v3+json'}})
  .then(function(r){ return r.json(); })
  .then(function(d){
    var entries = JSON.parse(blogDecodeContent(d.content));
    var e = entries[i];
    document.getElementById('blogTitle').value = e.title||'';
    document.getElementById('blogBody').value  = e.body||'';
    document.getElementById('blogEditIdx').value = i;
    document.getElementById('blogPostBtn').textContent = '· save edit ·';
    document.getElementById('blogWriteForm').scrollIntoView({behavior:'smooth'});
  });
}

function blogResetPassword(){
  if(!confirm('clear your saved password? your posts are not affected.')) return;
  localStorage.removeItem('mary_blog_pass_hash');
  blogLogout();
  document.getElementById('blogAuthStatus').textContent='· password cleared — click lock to set a new one ·';
}

